def add(n,title,m,e,deps,contracts,sections,requirements,files,scope,tests,done,role='Engine engineer',gate=None,command=None):
    ident=f'CUR-{n:03}'
    package={'E01':'currents-types','E02':'currents-storage','E03':'currents-domain','E04':'currents-domain','E05':'currents-planning','E06':'currents-storage','E07':'currents-ffi','E08':'currents-acquisition','E09':'currents-service'}[e]
