# Normalize prose spacing without altering file paths, symbols or command syntax.
def polish_prose(x):
    replacements={'Rust1':'Rust 1','SQLCipher4':'SQLCipher 4','SQLx0':'SQLx 0','iOS18':'iOS 18','macOS15':'macOS 15','Swift6':'Swift 6','upstream0':'upstream 0','floor0001':'floor 0001','min3':'minimum 3','latest6':'latest 6','buy0.':'buy 0.','sell0.':'sell 0.','cost100':'cost 100','gross120':'gross 120','cash115':'cash 115','fee5':'fee 5','basis36':'basis 36','gain16':'gain 16','30years':'30 years','100accounts':'100 accounts','1million':'1 million','10million':'10 million','6months':'6 months'}
    for a,b in replacements.items():x=x.replace(a,b)
    x=re.sub(r'(\d)(MiB|GiB|million|minutes|months|days|years|hours|records|operations|postings|Documents|ops|h|m|s)(?![A-Za-z_])',r'\1 \2',x)
    x=re.sub(r',(?=[A-Za-z])',', ',x)
    return x
for ticket in manifest['tickets']:
    for k in ['why','scope','non_goals','produces','done']:ticket[k]=polish_prose(ticket[k])
    for test in ticket['tests']:test['assertion']=polish_prose(test['assertion'])
    if ticket['gate']:
        ticket['gate']={k:polish_prose(v) for k,v in ticket['gate'].items()}
for row in manifest['milestones']:
    for k in ['description','exit_gate']:row[k]=polish_prose(row[k])
(ROOT/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
